contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _recipient, uint256 amount) public payable {
        require(_recipient != address(0), "recipient cannot be zero");
        require(address(this).balance >= amount, "not enough balance");

        address ownerBefore = c.owner();
        uint256 balBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll{value: amount}(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool isOwner = (msg.sender == ownerBefore);

        assert(
            reverted == !isOwner ||
            (isOwner && !reverted && address(c).balance == 0 && _recipient.balance >= balBefore + amount)
        );
    }

    receive() external payable {}
}

