contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, address attacker) public payable {
        // Ensure the test contract is the owner (it deployed c)
        require(address(this) == c.owner(), "test contract is not owner");
        // attacker must not be the owner (to trigger revert on second call)
        require(attacker != c.owner(), "attacker must not be owner");

        uint256 balBefore = address(c).balance;

        // First call: owner withdraws all funds to recipient (may revert if transfer fails, e.g., if recipient is a contract that rejects)
        bool reverted1;
        try c.withdrawAll(recipient) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // Second call: attacker (non-owner) attempts withdrawAll; must revert because msg.sender != owner
        // If attacker is the test contract? We already required attacker != owner, but attacker could be address(this)?
        // That would make msg.sender == owner? No, owner is address(this), so attacker==address(this) would be owner.
        // We required attacker != c.owner(), so attacker != address(this) as well, because owner == address(this).
        bool reverted2;
        try c.withdrawAll(attacker) {
            reverted2 = true; // should not happen
        } catch {
            reverted2 = false;
        }

        uint256 balAfter = address(c).balance;

        // General rule: If the first withdrawal did not revert (owner successfully withdrew), then contract balance becomes zero
        // and the second call from a non-owner reverts. If the first withdrawal reverted, the balance may be unchanged.
        // We assert a disjunction that holds for all inputs.
        assert((!reverted1 && balAfter == 0 && !reverted2) || (reverted1 && balAfter == balBefore && !reverted2));
    }

    receive() external payable {}
}
